-- Seed: attendance (حرمان) rules researched on 2026-09-25 from each university's
-- OFFICIAL regulation / registrar page, with the exact quote and link. All land
-- as `review`: nothing reaches students until an admin approves it in
-- Admin → University facts → Attendance policies. 21 Saudi universities
-- (4 from pre-1444 documents, flagged in `effective`/`note`) + 21 references
-- from other Arab countries (universities outside Haven's current list).

insert into public.attendance_policies
  (university_slug, university_name, country, method, max_absence, max_unexcused,
   excused_counts, excuse_floor_attendance, separate_components, component_limits,
   warnings, late_rule, details, effective, sources, note)
