($q$squ$q$, $q$جامعة السلطان قابوس$q$, $q$OM$q$, $q$hours$q$, 20, null, true, null, null, null, $q$[]$q$::jsonb, null, $q${"tiered_by_course_hours": [{"course_contact_hours": "<75", "warning_over": 10, "fw_over": 20}, {"course_contact_hours": "75-150", "warning_over": 5, "fw_over": 15}, {"course_contact_hours": ">150", "warning_over": 5, "fw_over": 10}]}$q$::jsonb, $q$Undergraduate Academic Regulations, 6th edition 2019$q$, $q$[{"url": "https://www.squ.edu.om/Portals/22/students/academic%20Regulations-en-2019.pdf?ver=gZAJ6_mPqQUYtSGFNCbCng%3D%3D", "title": "Sultan Qaboos University Undergraduate Academic Regulations (Sixth Edition 2019)", "quote": "An Absentee Withdrawal Notice will be issued and the student will be deemed to have withdrawn from the course with an FW grade if a student is absent for: 1. More than 20% of teaching hours that are less than 75 total contact hours. 2. More than 15% of teaching hours that have 75 to 150 total contact hours. 3. More than 10% of teaching hours for courses with more than 150 total contact hours."}]$q$::jsonb, $q$The limit DEPENDS ON THE COURSE SIZE: 20% (<75 contact hours), 15% (75-150), 10% (>150). Warning above 10% (small) or 5% (large). FW grade. Excused absences are listed separately (illness, bereavement, approved activities).$q$),
($q$syria-universities$q$, $q$سوريا - اللائحة التنفيذية لقانون تنظيم الجامعات (المرسوم 250 لعام 2007)$q$, $q$SY$q$, $q$unspecified$q$, null, null, true, null, null, null, $q$[]$q$::jsonb, null, $q${}$q$::jsonb, $q$Decree 250 of 2007, Article 84$q$, $q$[{"url": "https://au.edu.sy/storage/files/pdf_file/7kqAYNFQTh6fWLcE4d9g8hJT9EVEIwcuDcwGfT3t.pdf", "title": "اللائحة التنفيذية لقانون تنظيم الجامعات الصادرة بالمرسوم 250 تاريخ 10/7/2007", "quote": "يحرم الطالب من التقدم إلى امتحان المقرر الذي لم يحقق فيه نسبة الدوام المحددة في اللائحة الداخلية للكلية ويعد راسبا فيه"}]$q$::jsonb, $q$National rule leaves the percentage to EACH FACULTY bylaw (اللائحة الداخلية للكلية). No national number. Mostly applies to practical sessions in public universities.$q$),
($q$uaeu$q$, $q$جامعة الإمارات العربية المتحدة$q$, $q$AE$q$, $q$lectures$q$, 15, null, true, null, null, null, $q$[5, 10]$q$::jsonb, null, $q${"at_limit_fails": true}$q$::jsonb, $q$Policy ACA-ADM-06, 2004-09-05 (Chancellor Decree 128/2004)$q$, $q$[{"url": "https://www.uaeu.ac.ae/en/about/policies/pdf/pol_020206_en.pdf", "title": "UAEU Policy ACA-ADM-06 Attendance", "quote": "A student who misses 15% of the class meetings allotted for a course will fail the course. If there is a legitimate reason for the absence, which has been accepted by the dean ... the student will be granted a satisfactory withdrawal"}]$q$::jsonb, $q$Warnings at 5% and 10%; missing 15% of class meetings = fail (F). If the absences are excused and accepted by the dean, the student gets a withdrawal (W) instead of F. Policy dated 2004.$q$),
($q$um5-rabat$q$, $q$جامعة محمد الخامس - الرباط$q$, $q$MA$q$, $q$count$q$, null, null, true, null, null, null, $q$[]$q$::jsonb, null, $q${"count_rule": {"TP": {"max_unexcused_fraction": 0.3333}, "DUT": {"max_unexcused_sessions_per_module": 6}}}$q$::jsonb, $q$Normes pédagogiques complémentaires Licence et Master (UM5)$q$, $q$[{"url": "https://www.um5.ac.ma/um5/sites/default/files/Actualit%C3%A9%20acad%C3%A9mique/Normes%20p%C3%A9dagogiques%20Compl%C3%A9mentaires_%20Licence%20et%20Master.pdf", "title": "Normes pédagogiques complémentaires de licence et de master - Université Mohammed V de Rabat", "quote": "Les absences non justifiées à plus du tiers (1/3) des séances de travaux pratiques entraînent la non admission au contrôle final du module concerné ... tout étudiant qui s absente (absence non justifiée) au minimum à plus de 6 (six) séances par module ne sera pas autorisé à se présenter à l examen"}]$q$::jsonb, $q$Open-access programs (LEF): attendance mandatory, no numeric denial threshold stated. Selective programs (LP/M/MS): unexcused absence from more than 1/3 of lab sessions = not admitted to the final; technical programs (DUT): more than 6 unexcused sessions per module = not admitted.$q$),
($q$uob-bahrain$q$, $q$جامعة البحرين$q$, $q$BH$q$, $q$hours$q$, 25, null, true, null, null, null, $q$[15]$q$::jsonb, null, $q${}$q$::jsonb, $q$Study and Examination System regulation, version 02/2025 (original 23 Oct 2013)$q$, $q$[{"url": "https://governance.uob.edu.bh/wp-content/uploads/gravity_forms/1-5c61521fd6ccc367f92ae7eb104b9326/2026/08/9-Regulation_Study_and_Examination_System_EN.pdf", "title": "Study and Examination Regulation at the University of Bahrain (Version 02/2025)", "quote": "When the absence rate reaches (15%) of the course allocated hours, the student is given a written warning, and if the student is absent for a period exceeding (25%) of the course hours ... the student is considered to have compulsorily withdrawn ... with an acceptable excuse ... (WA) ... without an excuse ... (WF)"}]$q$::jsonb, $q$Written warning at 15% of course hours; over 25% = compulsory withdrawal: WA if excused, WF (counts as fail) if not. Excuses must be given within two lectures.$q$)
